from kivy.app import App
from kivy.uix.gridlayout import GridLayout
from kivy.uix.button import Button
from kivy.uix.behaviors.focus import FocusBehavior
from kivy.uix.behaviors.compoundselection import CompoundSelectionBehavior
from kivy.core.window import Window
from kivy.properties import ListProperty

class SelectableGrid(FocusBehavior, CompoundSelectionBehavior, GridLayout):
    selected_nodes = ListProperty([])

    def __init__(self, **kwargs):
        super().__init__(**kwargs)
        self._typed_number = ""
        self._keyboard = None
        self.bind(selected_nodes=self.on_selection_change)
        self.register_event_type('on_selection_change')
        self.bind(children=self._update_button_colors)

    def on_parent(self, instance, value):
        if value:
            self._request_keyboard()

    def _request_keyboard(self):
        if not self._keyboard:
            self._keyboard = Window.request_keyboard(self._keyboard_closed, self)
            if self._keyboard:
                self._keyboard.bind(on_key_down=self._on_keyboard_down, on_key_up=self._on_keyboard_up)

    def _keyboard_closed(self, *args):
        if self._keyboard:
            self._keyboard.unbind(on_key_down=self._on_keyboard_down, on_key_up=self._on_keyboard_up)
            self._keyboard = None

    def _on_keyboard_down(self, keyboard, keycode, text, modifiers):
        key, key_str = keycode
        if key_str.isdigit():
            self._typed_number += key_str
            self.goto_node_by_number(self._typed_number)
            return True
        elif key_str == 'enter':
            self._typed_number = ""
            return True
        elif key_str in ('up', 'down', 'left', 'right'):
            self._typed_number = ""
            self._navigate(key_str)
            return True
        elif key_str == 'spacebar':
            self._typed_number = ""
            self._toggle_selection()
            return True
        return False

    def _on_keyboard_up(self, keyboard, keycode):
        return False

    def goto_node_by_number(self, number_str):
        try:
            idx = int(number_str) - 1
            if 0 <= idx < len(self.children):
                node = self.children[::-1][idx]
                self.select_node(node)
        except Exception:
            pass

    def select_node(self, node):
        if node not in self.selected_nodes:
            self.selected_nodes.append(node)
            self._update_button_colors()
            self.dispatch('on_selection_change', self.selected_nodes)

    def deselect_node(self, node):
        if node in self.selected_nodes:
            self.selected_nodes.remove(node)
            self._update_button_colors()
            self.dispatch('on_selection_change', self.selected_nodes)

    def clear_selection(self):
        self.selected_nodes = []
        self._update_button_colors()
        self.dispatch('on_selection_change', self.selected_nodes)

    def _toggle_selection(self):
        focus_node = self._get_focused_node()
        if focus_node:
            if focus_node in self.selected_nodes:
                self.deselect_node(focus_node)
            else:
                self.select_node(focus_node)

    def _get_focused_node(self):
        for child in self.children:
            if hasattr(child, 'focus') and child.focus:
                return child
        return None

    def _navigate(self, direction):
        focus_node = self._get_focused_node()
        if not focus_node:
            if self.children:
                self.children[-1].focus = True
            return
        idx = self.children[::-1].index(focus_node)
        cols = self.cols
        rows = self.rows if self.rows else (len(self.children) // cols)
        if direction == 'right':
            new_idx = idx + 1 if (idx + 1) < len(self.children) else idx
        elif direction == 'left':
            new_idx = idx - 1 if (idx - 1) >= 0 else idx
        elif direction == 'up':
            new_idx = idx - cols if (idx - cols) >= 0 else idx
        elif direction == 'down':
            new_idx = idx + cols if (idx + cols) < len(self.children) else idx
        else:
            new_idx = idx
        for child in self.children:
            if hasattr(child, 'focus'):
                child.focus = False
        self.children[::-1][new_idx].focus = True

    def select_with_touch(self, node, touch=None):
        self.select_node(node)

    def on_touch_down(self, touch):
        for child in self.children:
            if child.collide_point(*touch.pos):
                self.select_with_touch(child, touch)
                return True
        return super().on_touch_down(touch)

    def _update_button_colors(self, *args):
        for child in self.children:
            if child in self.selected_nodes:
                child.background_color = (0.2, 0.6, 1, 1)
            else:
                child.background_color = (1, 1, 1, 1)

    def on_selection_change(self, instance, selected_nodes):
        print("Selected nodes:", [btn.text for btn in selected_nodes])

class TestApp(App):
    def build(self):
        grid = SelectableGrid(cols=8, spacing=5, padding=5)
        for i in range(1, 41):
            btn = Button(text=str(i), focus=False)
            btn.bind(on_touch_down=lambda instance, touch, btn=btn: grid.on_touch_down(touch))
            grid.add_widget(btn)
        return grid

if __name__ == '__main__':
    TestApp().run()
